# ---------------------------------------------------------------------------
# rv (Ruby version manager) probes
# ---------------------------------------------------------------------------

RV_RUBIES_DIR = Path.home() / "AppData" / "Roaming" / "rv" / "rubies"


def rv_available() -> bool:
    proc = run(["rv", "--version"])
    return proc.returncode == 0


def rv_ruby_list() -> tuple[bool, str]:
    proc = run(["rv", "ruby", "list"])
    ok = proc.returncode == 0
    return ok, (proc.stdout + proc.stderr).strip()


def rv_active_ruby() -> str:
    """Return the currently pinned/active ruby version, or 'none'."""
    proc = run(["rv", "ruby", "current"])
    if proc.returncode == 0 and proc.stdout.strip():
        return proc.stdout.strip()
    # Fallback: inspect .ruby-version in repo root.
    pin_file = REPO_ROOT / ".ruby-version"
    if pin_file.exists():
        return pin_file.read_text(encoding="utf-8").strip()
    return "none"


def rv_stale_installer_dirs() -> list[Path]:
    """Return leftover rubyinstaller-* dirs that block rename operations."""
    if not RV_RUBIES_DIR.exists():
        return []
    return [p for p in RV_RUBIES_DIR.iterdir()
            if p.is_dir() and p.name.startswith("rubyinstaller-")]


def rv_remove_stale_installers(stale: list[Path]) -> list[str]:
    """Forcibly remove stale rubyinstaller-* directories."""
    import shutil
    removed: list[str] = []
    for p in stale:
        try:
            shutil.rmtree(p)
            removed.append(str(p))
        except Exception as e:  # noqa: BLE001
            removed.append(f"FAILED {p}: {e}")
    return removed

