// WSL2 Ruby ZJIT shim — self-naming forwarder
// Copy as ruby.exe, gem.exe, bundle.exe, irb.exe, rake.exe etc.
// Each exe routes to /opt/ruby-zjit/<own_stem> in podman-machine-default.
use std::process::{Command, exit};

fn main() {
    let exe = std::env::current_exe().expect("cannot resolve own path");
    let stem = exe
        .file_stem()
        .expect("no file stem")
        .to_string_lossy()
        .to_string();

    // Passthrough args, skipping argv[0]
    let args: Vec<String> = std::env::args().skip(1).collect();

    let target = format!("/opt/ruby-zjit/bin/{}", stem);

    let status = Command::new("wsl")
        .args(["-d", "podman-machine-default", "-u", "root", "--", &target])
        .args(&args)
        .status()
        .unwrap_or_else(|e| {
            eprintln!("wsl2-ruby-shim: failed to launch wsl: {}", e);
            exit(127);
        });

    exit(status.code().unwrap_or(1));
}

