# SID: patch-jit-win32
# Patches Ruby jit.c to add Win32 (VirtualAlloc/VirtualProtect) memory-management
# implementations alongside the existing POSIX paths.
# Run from the Ruby source root: python3 patch-jit-win32.py [--dry-run]
#
# Target: Ruby 4.0.x jit.c
# Changes: 5 targeted substitutions — no logic removed, only #ifdef blocks added.

import sys
import re
from pathlib import Path

DRY_RUN = "--dry-run" in sys.argv

JIT_C = Path("jit.c")
if not JIT_C.exists():
    print(f"ERROR: {JIT_C} not found. Run from the Ruby source root.", file=sys.stderr)
    sys.exit(1)

original = JIT_C.read_text(encoding="utf-8")
patched = original

# ── 1. Conditional windows.h include ─────────────────────────────────────────
# Insert after the last #include block, before any blank-line + code.
WIN_INCLUDE = '#ifdef _WIN32\n#include <windows.h>\n#endif\n'

INCLUDE_MARKER = '#include "internal/string.h"\n'
if WIN_INCLUDE not in patched:
    patched = patched.replace(
        INCLUDE_MARKER,
        INCLUDE_MARKER + WIN_INCLUDE,
        1
    )

# ── 2. rb_jit_get_page_size: add #elif _WIN32 path ───────────────────────────
OLD_PAGE_SIZE = '''\
#if defined(_SC_PAGESIZE)
    long page_size = sysconf(_SC_PAGESIZE);
    if (page_size <= 0) rb_bug("jit: failed to get page size");

    // 1 GiB limit. x86 CPUs with PDPE1GB can do this and anything larger is unexpected.
    // Though our design sort of assume we have fine grained control over memory protection
    // which require small page sizes.
    if (page_size > 0x40000000l) rb_bug("jit page size too large");

    return (uint32_t)page_size;
#else
#error "JIT supports POSIX only for now"
#endif'''

NEW_PAGE_SIZE = '''\
#if defined(_SC_PAGESIZE)
    long page_size = sysconf(_SC_PAGESIZE);
    if (page_size <= 0) rb_bug("jit: failed to get page size");

    // 1 GiB limit. x86 CPUs with PDPE1GB can do this and anything larger is unexpected.
    // Though our design sort of assume we have fine grained control over memory protection
    // which require small page sizes.
    if (page_size > 0x40000000l) rb_bug("jit page size too large");

    return (uint32_t)page_size;
#elif defined(_WIN32)
    SYSTEM_INFO si;
    GetSystemInfo(&si);
    if (si.dwPageSize > 0x40000000ul) rb_bug("jit page size too large");
    return (uint32_t)si.dwPageSize;
#else
#error "JIT supports POSIX only for now"
#endif'''

assert OLD_PAGE_SIZE in original, "PATCH 2 anchor not found in jit.c — version mismatch?"
patched = patched.replace(OLD_PAGE_SIZE, NEW_PAGE_SIZE, 1)

# ── 3. rb_jit_reserve_addr_space: replace NULL Windows stub ──────────────────
OLD_RESERVE = '''\
#else
    // Windows not supported for now
    return NULL;
#endif
}'''

NEW_RESERVE = '''\
#else
    // Windows: use VirtualAlloc to reserve address space near the JIT code
    // so 32-bit relative calls remain in range.
    SYSTEM_INFO si;
    GetSystemInfo(&si);
    DWORD granularity = si.dwAllocationGranularity;

    uint8_t *const cfunc_addr = (uint8_t *)(uintptr_t)&rb_jit_reserve_addr_space;
    // Align downward to allocation granularity
    uintptr_t aligned = ((uintptr_t)cfunc_addr / granularity) * granularity;
    uint8_t *req_addr = (uint8_t *)aligned;

    uint8_t *mem_block = NULL;
    // Probe downward within INT32_MAX of the JIT code for near-address reservation
    while (req_addr > cfunc_addr - (uintptr_t)INT32_MAX) {
        mem_block = VirtualAlloc(req_addr, mem_size, MEM_RESERVE, PAGE_NOACCESS);
        if (mem_block) break;
        if (req_addr < (uint8_t *)granularity) break; // underflow guard
        req_addr -= granularity;
    }

    // Fallback: let Windows choose any address
    if (!mem_block) {
        mem_block = VirtualAlloc(NULL, mem_size, MEM_RESERVE, PAGE_NOACCESS);
    }

    if (!mem_block) {
        rb_bug("VirtualAlloc reserve failed: error %lu", (unsigned long)GetLastError());
    }

    return mem_block;
#endif
}'''

assert OLD_RESERVE in original, "PATCH 3 anchor not found in jit.c — version mismatch?"
patched = patched.replace(OLD_RESERVE, NEW_RESERVE, 1)

# ── 4. rb_jit_mark_writable ───────────────────────────────────────────────────
OLD_WRITABLE = '''\
bool
rb_jit_mark_writable(void *mem_block, uint32_t mem_size)
{
    return mprotect(mem_block, mem_size, PROT_READ | PROT_WRITE) == 0;
}'''

NEW_WRITABLE = '''\
bool
rb_jit_mark_writable(void *mem_block, uint32_t mem_size)
{
#ifdef _WIN32
    DWORD old_protect;
    return VirtualProtect(mem_block, mem_size, PAGE_READWRITE, &old_protect) != 0;
#else
    return mprotect(mem_block, mem_size, PROT_READ | PROT_WRITE) == 0;
#endif
}'''

assert OLD_WRITABLE in original, "PATCH 4 anchor not found in jit.c — version mismatch?"
patched = patched.replace(OLD_WRITABLE, NEW_WRITABLE, 1)

# ── 5. rb_jit_mark_executable ─────────────────────────────────────────────────
OLD_EXEC = '''\
    if (mprotect(mem_block, mem_size, PROT_READ | PROT_EXEC)) {
        rb_bug("Couldn't make JIT page (%p, %lu bytes) executable, errno: %s",
            mem_block, (unsigned long)mem_size, strerror(errno));
    }
}'''

NEW_EXEC = '''\
#ifdef _WIN32
    DWORD old_protect;
    if (!VirtualProtect(mem_block, mem_size, PAGE_EXECUTE_READ, &old_protect)) {
        rb_bug("Couldn't make JIT page (%p, %lu bytes) executable, error: %lu",
            mem_block, (unsigned long)mem_size, (unsigned long)GetLastError());
    }
#else
    if (mprotect(mem_block, mem_size, PROT_READ | PROT_EXEC)) {
        rb_bug("Couldn't make JIT page (%p, %lu bytes) executable, errno: %s",
            mem_block, (unsigned long)mem_size, strerror(errno));
    }
#endif
}'''

assert OLD_EXEC in original, "PATCH 5 anchor not found in jit.c — version mismatch?"
patched = patched.replace(OLD_EXEC, NEW_EXEC, 1)

# ── 6. rb_jit_mark_unused ─────────────────────────────────────────────────────
OLD_UNUSED = '''\
    // On Linux, you need to use madvise MADV_DONTNEED to free memory.
    // We might not need to call this on macOS, but it's not really documented.
    // We generally prefer to do the same thing on both to ease testing too.
    madvise(mem_block, mem_size, MADV_DONTNEED);

    // On macOS, mprotect PROT_NONE seems to reduce RSS.
    // We also call this on Linux to avoid executing unused pages.
    return mprotect(mem_block, mem_size, PROT_NONE) == 0;
}'''

NEW_UNUSED = '''\
#ifdef _WIN32
    // MEM_RESET tells Windows the pages can be discarded (equivalent to MADV_DONTNEED).
    VirtualAlloc(mem_block, mem_size, MEM_RESET, PAGE_NOACCESS);
    DWORD old_protect;
    return VirtualProtect(mem_block, mem_size, PAGE_NOACCESS, &old_protect) != 0;
#else
    // On Linux, you need to use madvise MADV_DONTNEED to free memory.
    // We might not need to call this on macOS, but it's not really documented.
    // We generally prefer to do the same thing on both to ease testing too.
    madvise(mem_block, mem_size, MADV_DONTNEED);

    // On macOS, mprotect PROT_NONE seems to reduce RSS.
    // We also call this on Linux to avoid executing unused pages.
    return mprotect(mem_block, mem_size, PROT_NONE) == 0;
#endif
}'''

assert OLD_UNUSED in original, "PATCH 6 anchor not found in jit.c — version mismatch?"
patched = patched.replace(OLD_UNUSED, NEW_UNUSED, 1)

# ── Summary ───────────────────────────────────────────────────────────────────
changes = sum(1 for a, b in zip(original.splitlines(), patched.splitlines()) if a != b)
print(f"Patches applied — {len(patched) - len(original):+d} bytes, ~{changes} lines changed")

if DRY_RUN:
    print("DRY RUN — jit.c not written")
else:
    JIT_C.write_text(patched, encoding="utf-8")
    print("jit.c written.")
"}

