#   uv run python C:\...\build\ruby-zjit\patch-rust-win32.py [--dry-run]

import sys
from pathlib import Path

DRY_RUN = "--dry-run" in sys.argv
SRC = Path(sys.argv[1]) if len([a for a in sys.argv[1:] if not a.startswith("--")]) > 0 \
    else Path(".")

errors = []

def patch(rel_path: str, old: str, new: str, count: int = 1) -> bool:
    p = SRC / rel_path
    if not p.exists():
        errors.append(f"MISSING: {rel_path}")
        return False
    text = p.read_text(encoding="utf-8")
    actual = text.count(old)
    if actual == 0:
        errors.append(f"ANCHOR NOT FOUND: {rel_path}  >>>  {old[:80].strip()!r}")
        return False
    if count != -1 and actual != count:
        errors.append(f"AMBIGUOUS: {rel_path} — expected {count} match(es), found {actual}  >>>  {old[:80].strip()!r}")
        return False
    patched = text.replace(old, new) if count == -1 else text.replace(old, new, count)
    if not DRY_RUN:
        p.write_text(patched, encoding="utf-8")
    return True

results = []

