replacements.newString:
// GCC 15.x: combining -O3 with warning-analysis flags causes "error reporting routines
// re-entered" ICE. The analysis runs inside Ruby headers (vm_core.h, internal.h, etc.)
// during O3 optimization passes. Suppress all O3-dependent warning analyses for this TU.
// Note: the build.sh also strips warnflags from the generated Makefile as the primary fix.
#pragma GCC diagnostic ignored "-Wundef"
#pragma GCC diagnostic ignored "-Wsuggest-attribute=noreturn"
#pragma GCC diagnostic ignored "-Wsuggest-attribute=format"
#pragma GCC diagnostic ignored "-Wsuggest-attribute=pure"
#pragma GCC diagnostic ignored "-Wmissing-noreturn"
#pragma GCC diagnostic ignored "-Wmaybe-uninitialized"
#pragma GCC diagnostic ignored "-Warray-bounds"
#pragma GCC diagnostic ignored "-Wnull-dereference"

