# KEY FIX (2026-04-22): VirtualProtect fails on MEM_RESERVE-only (uncommitted) pages.
# ZJIT code regions are reserved via MEM_RESERVE but not committed until gen_entry_trampoline.
# VirtualAlloc(MEM_COMMIT, PAGE_READWRITE) atomically commits + grants write permission;
# idempotent on already-committed pages. VirtualProtect requires committed pages.
OLD_WRITABLE = '''\
bool
rb_jit_mark_writable(void *mem_block, uint32_t mem_size)
{
    return mprotect(mem_block, mem_size, PROT_READ | PROT_WRITE) == 0;
}'''

