# Session lifecycle — bounds every pwsh session with XP arc (start snapshot + exit delta).
# Guard: $env:CHTHONIC_SESSION_ID not set — prevents double-registration in nested shells.
$_cthTrailDir = Join-Path $env:USERPROFILE 'chthonic-archive\.chthonic\trail'
if ((Test-Path $_cthTrailDir) -and -not $env:CHTHONIC_SESSION_ID) {
    $env:CHTHONIC_SESSION_ID     = ([System.Guid]::NewGuid().ToString('N')).Substring(0, 8)
    $env:CHTHONIC_TRAIL_DIR      = $_cthTrailDir

    # Pre-session XP snapshot from state file — no trail I/O at startup
    $_cthStateFile = Join-Path $env:USERPROFILE 'chthonic-archive\.chthonic\xp-state.json'
    $_cthPreState  = if (Test-Path $_cthStateFile) { try { Get-Content $_cthStateFile -Raw | ConvertFrom-Json } catch { $null } }
    $env:CHTHONIC_SESSION_PRE_XP = if ($_cthPreState -and $_cthPreState.xp) { [string][int]$_cthPreState.xp } else { '0' }

    # Env detection — path-check only, zero subprocess (matches xp.ps1 probe)
    $_cthZjitTag = $null
    $_cthMsys2On = $false
    try {
        $_cthRubyCmd = Get-Command ruby -ErrorAction SilentlyContinue
        if ($_cthRubyCmd -and $_cthRubyCmd.Source -match '\\rubies\\ruby-([^\\]+)\\bin\\ruby') { $_cthZjitTag = $matches[1] }
    } catch {}
    try {
        $_cthMsysRoot = if ($env:MSYS2_HOME) { $env:MSYS2_HOME } elseif ($env:RI_DEVKIT) { $env:RI_DEVKIT } else { $null }
        if ($_cthMsysRoot -and (Test-Path (Join-Path $_cthMsysRoot 'ucrt64\bin\gcc.exe'))) { $_cthMsys2On = $true }
    } catch {}

    # Emit session_start with env metadata — recorded to trail, no XP earned (bookkeeping)
    $_cthTodayFile = Join-Path $_cthTrailDir "$((Get-Date -Format 'yyyy-MM-dd')).hot.ndjson"
    Add-Content -Path $_cthTodayFile -Encoding UTF8 -ErrorAction SilentlyContinue -Value (
        [ordered]@{
            ts    = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
            type  = 'meta'; kind = 'session_start'; p = 3
            sid   = $env:CHTHONIC_SESSION_ID
            msg   = 'pwsh session start'
            zjit  = $_cthZjitTag
            msys2 = $_cthMsys2On
        } | ConvertTo-Json -Compress)

    # Exit hook — writes session_end delta to trail when shell closes (file write only)
    Register-EngineEvent PowerShell.Exiting -Action {
        $sid      = $env:CHTHONIC_SESSION_ID
        $trailDir = $env:CHTHONIC_TRAIL_DIR
        $preXP    = try { [int]$env:CHTHONIC_SESSION_PRE_XP } catch { 0 }
        if (-not $sid -or -not (Test-Path $trailDir)) { return }
        $stateFile = Join-Path $env:USERPROFILE 'chthonic-archive\.chthonic\xp-state.json'
        $post   = if (Test-Path $stateFile) { try { Get-Content $stateFile -Raw | ConvertFrom-Json } catch { $null } }
        $postXP = if ($post -and $post.xp) { [int]$post.xp } else { $preXP }
        $delta  = $postXP - $preXP
        $todayFile = Join-Path $trailDir "$((Get-Date -Format 'yyyy-MM-dd')).hot.ndjson"
        Add-Content -Path $todayFile -Encoding UTF8 -ErrorAction SilentlyContinue -Value (
            [ordered]@{
                ts       = [DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds()
                type     = 'meta'; kind = 'session_end'; p = 3
                sid      = $sid
                msg      = "pwsh session end (+$delta XP)"
                xp_delta = $delta
                xp_after = $postXP
            } | ConvertTo-Json -Compress)
    } | Out-Null
}

