    let mut hasher = Sha256::new();
    hasher.update(&header_for_hash);
    hasher.update(schema_bytes);
    hasher.update(spirv_bytes);
    hasher.update(payload_compressed);
    let computed: [u8; 32] = hasher.finalize().into();
    if computed != stored_hash {
