    $Choice = (Read-Host "Select GPU [A/B]").ToUpper()
    while ($Choice -notin @("A","B")) {
        $Choice = (Read-Host "Invalid. Select GPU [A/B]").ToUpper()
    }

    if ($Choice -eq "B") {
        Write-Host "ERROR: AMD is not supported on Windows. Use Linux + ROCm 6.4."
        exit 1
    }

    return "cu12"
}

# ── Dependency sync ────────────────────────────────────────────────────────────
if ($FirstRun -or $UpdateDeps) {
    $ResolvedLib = if ($NoWheel) { $null } else { Resolve-GpuLib -Hint $GpuLib }

    $Features = if ($ResolvedLib) { ".[$ResolvedLib]" } else { "." }
    $SyncArgs  = @("pip", "install", "-U")

    if ($ForceReinstall) { $SyncArgs += "--force-reinstall" }
    $SyncArgs += $Features

    Write-Host "Running: uv $($SyncArgs -join ' ')"
    Push-Location $RepoRoot
    uv @SyncArgs
    Pop-Location

    # Save state
    if ($ResolvedLib) {
        $StartOptions["gpu_lib"] = $ResolvedLib
    }

    if ($FirstRun) {
        $StartOptions["first_run_done"] = $true
        Write-Host "Dependencies installed."
    }

    # Persist start_options.json
    $StartOptions | ConvertTo-Json -Depth 5 | Set-Content -Path $StartOptionsPath -Encoding UTF8
    Write-Host "Saved preferences to start_options.json"

    if ($UpdateDeps) {
        Write-Host "Dependencies updated. Run .\start.ps1 to launch tabbyAPI."
        exit 0
    }
}

# ── Config bootstrap (first run only) ─────────────────────────────────────────
if (-not (Test-Path $ConfigPath) -and (Test-Path $ConfigSamplePath)) {
    Copy-Item $ConfigSamplePath $ConfigPath
    Write-Host "Created config.yml from config_sample.yml"
}

# ── Launch ─────────────────────────────────────────────────────────────────────
Write-Host "Starting tabbyAPI..."
Push-Location $RepoRoot

$UvArgs = @("run", "main.py") + $PassThrough
uv @UvArgs

Pop-Location
"}

arguments.content:
#!/usr/bin/env pwsh
# @SID: TABBY_START_PS1_V1
# Archive-native launcher for tabbyAPI on Windows (pwsh 7.x + uv)
# Replaces: start.bat + the install-phase of start.py
# Passes all remaining args through to main.py (host, port, model, config, etc.)
#
# Usage:
#   .\start.ps1                           # auto-detect GPU, sync deps on first run, start API
#   .\start.ps1 --gpu-lib cu12            # force CUDA backend
#   .\start.ps1 --gpu-lib amd            # force AMD backend (Linux only)
#   .\start.ps1 --update-deps            # sync deps then exit
#   .\start.ps1 --update-deps --update-repository  # pull + sync deps then exit
#   .\start.ps1 --force-reinstall --update-deps    # force reinstall all deps
#   .\start.ps1 --host 0.0.0.0 --port 5001         # pass-through to main.py

param(
    [string]  $GpuLib            = "",   # cu12 | amd | "" (auto-detect)
    [switch]  $UpdateDeps,               # sync deps then exit
    [switch]  $UpdateRepository,         # git pull before sync
    [switch]  $ForceReinstall,           # --reinstall flag for uv sync
    [switch]  $NoWheel,                  # skip GPU-specific extras
    [Parameter(ValueFromRemainingArguments = $true)]
    [string[]] $PassThrough              # forwarded verbatim to main.py
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

# ── Paths ──────────────────────────────────────────────────────────────────────
$RepoRoot         = $PSScriptRoot
$StartOptionsPath = Join-Path $RepoRoot "start_options.json"
$ConfigSamplePath = Join-Path $RepoRoot "config_sample.yml"
$ConfigPath       = Join-Path $RepoRoot "config.yml"

# ── Toolchain guard ────────────────────────────────────────────────────────────
if (-not (Get-Command uv -ErrorAction SilentlyContinue)) {
    Write-Error "uv not found. Install via: winget install astral-sh.uv"
    exit 1
}

# ── Start options SSOT (replaces start_options.json read/write in start.py) ───
$StartOptions = [ordered]@{}
if (Test-Path $StartOptionsPath) {
    $StartOptions = Get-Content $StartOptionsPath -Raw | ConvertFrom-Json -AsHashtable
    Write-Host "Loaded saved preferences from start_options.json"
} else {
    Write-Host "First run — getting things ready..."
}

# Migrate legacy keys (cu121/cu118 -> cu12)
if ($StartOptions.ContainsKey("gpu_lib")) {
    $Legacy = $StartOptions["gpu_lib"]
    if ($Legacy -eq "cu121" -or $Legacy -eq "cu118") {
        Write-Host "GPU lib key is legacy ($Legacy), migrating to cu12"
        $StartOptions["gpu_lib"] = "cu12"
    }
}

$FirstRun = -not ($StartOptions.ContainsKey("first_run_done") -and $StartOptions["first_run_done"])

# ── git pull ───────────────────────────────────────────────────────────────────
if ($UpdateRepository) {
    Write-Host "Pulling latest changes from GitHub..."
    Push-Location $RepoRoot
    git pull
    Pop-Location
}

# ── GPU backend resolution ─────────────────────────────────────────────────────
function Resolve-GpuLib {
    param([string] $Hint)

    $Possible = @("cu12", "amd")

    if ($Hint -and $Possible -contains $Hint) {
        Write-Host "Using GPU lib: $Hint (from argument)"
        return $Hint
    }

    # Check saved preference
    if ($StartOptions.ContainsKey("gpu_lib") -and $StartOptions["gpu_lib"]) {
        $Saved = $StartOptions["gpu_lib"]
        if ($Possible -contains $Saved) {
            Write-Host "Using GPU lib: $Saved (from start_options.json)"
            return $Saved
        }
    }

    # Auto-detect via smi tools
    $HasNvidia = $null -ne (Get-Command nvidia-smi -ErrorAction SilentlyContinue)
    $HasRocm   = $null -ne (Get-Command rocm-smi   -ErrorAction SilentlyContinue)
    $HasAmd    = $null -ne (Get-Command amd-smi     -ErrorAction SilentlyContinue)
    $HasAmdGpu = $HasRocm -or $HasAmd

    if ($HasNvidia -and -not $HasAmdGpu) {
        Write-Host "Auto-detected NVIDIA GPU. Using CUDA 12.x backend."
        return "cu12"
    }

    if ($HasAmdGpu -and -not $HasNvidia) {
        Write-Host "Auto-detected AMD GPU."
        Write-Host "ERROR: tabbyAPI does not support AMD on Windows. Use Linux + ROCm 6.4."
        exit 1
    }

    # RTX 4090 default — no SMI ambiguity, fall through to prompt only in CI-less context
    if ($env:CI -or $env:TABBY_GPU_LIB) {
        $EnvLib = if ($env:TABBY_GPU_LIB) { $env:TABBY_GPU_LIB } else { "cu12" }
        Write-Host "CI/env fallback: using GPU lib $EnvLib"
        return $EnvLib
    }

    # Interactive choice — last resort
    Write-Host ""
    Write-Host "WARNING: GPU auto-detection failed."
    Write-Host "  A) NVIDIA CUDA 12.x"
    Write-Host "  B) AMD (Linux + ROCm 6.4 only)"
    Write-Host ""
    $Choice = (Read-Host "Select GPU [A/B]").ToUpper()
    while ($Choice -notin @("A","B")) {
        $Choice = (Read-Host "Invalid. Select GPU [A/B]").ToUpper()
    }

    if ($Choice -eq "B") {
        Write-Host "ERROR: AMD is not supported on Windows. Use Linux + ROCm 6.4."
        exit 1
    }

    return "cu12"
}

# ── Dependency sync ────────────────────────────────────────────────────────────
if ($FirstRun -or $UpdateDeps) {
    $ResolvedLib = if ($NoWheel) { $null } else { Resolve-GpuLib -Hint $GpuLib }

    $Features = if ($ResolvedLib) { ".[$ResolvedLib]" } else { "." }
    $SyncArgs  = @("pip", "install", "-U")

    if ($ForceReinstall) { $SyncArgs += "--force-reinstall" }
    $SyncArgs += $Features

    Write-Host "Running: uv $($SyncArgs -join ' ')"
    Push-Location $RepoRoot
    uv @SyncArgs
    Pop-Location

    # Save state
    if ($ResolvedLib) {
        $StartOptions["gpu_lib"] = $ResolvedLib
    }

    if ($FirstRun) {
        $StartOptions["first_run_done"] = $true
        Write-Host "Dependencies installed."
    }

    # Persist start_options.json
    $StartOptions | ConvertTo-Json -Depth 5 | Set-Content -Path $StartOptionsPath -Encoding UTF8
    Write-Host "Saved preferences to start_options.json"

    if ($UpdateDeps) {
        Write-Host "Dependencies updated. Run .\start.ps1 to launch tabbyAPI."
        exit 0
    }
}

# ── Config bootstrap (first run only) ─────────────────────────────────────────
if (-not (Test-Path $ConfigPath) -and (Test-Path $ConfigSamplePath)) {
    Copy-Item $ConfigSamplePath $ConfigPath
    Write-Host "Created config.yml from config_sample.yml"
}

# ── Launch ─────────────────────────────────────────────────────────────────────
Write-Host "Starting tabbyAPI..."
Push-Location $RepoRoot

$UvArgs = @("run", "main.py") + $PassThrough
uv @UvArgs

Pop-Location

