// ╔════════════════════════════════════════════════════════════════════════════
// ║ ci/checks/toolchain-smoke.ts
// ║ Gate: verify the tabbyAPI build toolchain manifest is in admitted state.
// ╠════════════════════════════════════════════════════════════════════════════
// ║ Asserts manifest/vs2022_flash_attn_probe.json (P-06 output) exists and:
// ║   - build_result === "SUCCESS"
// ║   - build_exit_code === 0
// ║   - flash_attn version is present
// ║   - MSVC version starts with 14.4 (14.44.x series, not VS18 14.51)
// ║
// ║ Does NOT recompile. Zero compilation. Manifest assertion only.
// ║ For the full build, use: VS Code Task "Chthonic: flash_attn full rebuild"
// ║
// ║ Staged mode (--staged):
// ║   Only activates when probes/python/ or manifest/ files are staged.
// ║
// ║ Default mode:
// ║   Always runs.
// ╚════════════════════════════════════════════════════════════════════════════

import { existsSync, readFileSync } from "fs";
import { resolve } from "path";
import { spawnSync } from "child_process";

const REPO_ROOT = resolve(import.meta.dir, "../..");
const MANIFEST_PATH = resolve(REPO_ROOT, "manifest", "vs2022_flash_attn_probe.json");
const STAGED = process.argv.includes("--staged");

function stagedRelevantFiles(): boolean {
  const result = spawnSync(
    "git",
    ["diff", "--cached", "--name-only", "--diff-filter=ACMR"],
    { encoding: "utf8", cwd: REPO_ROOT }
  );
  const files = (result.stdout ?? "").split("\n").filter(Boolean);
  return files.some(
    (f) => f.startsWith("probes/python/") || f.startsWith("manifest/")
  );
}

if (STAGED && !stagedRelevantFiles()) {
  console.log("[toolchain-smoke] No staged probes/manifest files — skipping");
  process.exit(0);
}

// --- Manifest check ---

if (!existsSync(MANIFEST_PATH)) {
  console.error(
    "[toolchain-smoke] ✗ manifest/vs2022_flash_attn_probe.json not found.\n" +
    "  Run probes/python/vs2022_flash_attn_probe.py to generate it."
  );
  process.exit(1);
}

let manifest: Record<string, unknown>;
try {
  manifest = JSON.parse(readFileSync(MANIFEST_PATH, "utf8"));
} catch (e) {
  console.error(`[toolchain-smoke] ✗ Failed to parse manifest JSON: ${e}`);
  process.exit(1);
}

const failures: string[] = [];

// Assert build success
if (manifest["build_result"] !== "SUCCESS") {
  failures.push(
    `build_result expected "SUCCESS", got ${JSON.stringify(manifest["build_result"])}`
  );
}

if (manifest["build_exit_code"] !== 0) {
  failures.push(
    `build_exit_code expected 0, got ${JSON.stringify(manifest["build_exit_code"])}`
  );
}

// Assert MSVC version is 14.4x (not 14.51 VS18 Insiders)
const msvcVersion = manifest["vs2022_version"] as string | undefined;
if (!msvcVersion) {
  failures.push("vs2022_version missing from manifest");
} else if (!msvcVersion.startsWith("14.4")) {
  failures.push(
    `vs2022_version must start with "14.4" (CUDA 12.8 ceiling), got "${msvcVersion}"`
  );
}

// Assert flash_attn version present
const flashVersion = manifest["flash_attn_version"] as string | undefined;
if (!flashVersion) {
  failures.push("flash_attn_version missing from manifest");
}

// Assert gate status
const level = manifest["level"] as string | undefined;
if (!level || !level.startsWith("L")) {
  failures.push(`level missing or malformed, got ${JSON.stringify(level)}`);
} else if (level === "L0") {
  failures.push(`level is L0 — gate not admitted`);
}

if (failures.length > 0) {
  console.error("[toolchain-smoke] ✗ Toolchain manifest assertions failed:");
  for (const f of failures) {
    console.error(`  - ${f}`);
  }
  process.exit(1);
}

console.log(
  `[toolchain-smoke] ✓ Toolchain admitted — flash_attn ${flashVersion} | MSVC ${msvcVersion} | ${level}`
);
process.exit(0);
"}

