  );
}

// Output
if (REPORT) {
  console.log(JSON.stringify(result, null, 2));
} else {
  const icon = result.status === "healthy" ? "✓" : result.status === "degraded" ? "⚠" : "✗";
  const dispatchMsg = dispatchFails > 0 ? ` dispatch_failures=${dispatchFails}` : "";
